export function getRoom(id) {
  return ROOMS.find((r) => r.id === id) || null;
}

export function roomsInCollection(collection) {
  return ROOMS.filter((r) => r.collection === collection).sort((a, b) => a.order - b.order);
}

/** Which categories a room actually uses — drives the HUD and progress weights. */
export function roomCategories(room) {
  const cats = [];
  if (room.trash?.length) cats.push("trash");
  if (room.dust?.length) cats.push("dust");
  if (room.floor?.length) cats.push("floor");
  if (room.glass?.length) cats.push("glass");
  if (room.stains?.length) cats.push("stains");
  if (room.dishes?.length) cats.push("dishes");
  if (room.organize?.length) cats.push("organize");
  if (room.bed) cats.push("bed");
  return cats;
}
